import { memo } from 'react';
import type { AnyNode } from '../specification/nodes';
import { AMP_LAYER_STACK_BASE } from '../specification/canvas';
import { runtimeLayoutStyle } from './layout';
import { RuntimeAudio } from './nodes/RuntimeAudio';
import { RuntimeDivider } from './nodes/RuntimeDivider';
import { RuntimeImage } from './nodes/RuntimeImage';
import { RuntimeModel3D } from './model3d/RuntimeModel3D';
import { RuntimeTable } from './nodes/RuntimeTable';
import { RuntimeText } from './nodes/RuntimeText';
import { RuntimeVideo } from './nodes/RuntimeVideo';

export const RuntimeNode = memo(function RuntimeNode({ node, layerIndex }: { node: AnyNode; layerIndex: number }) {
  const style = runtimeLayoutStyle(node.layout, node.style);
  // Author stores Photoshop-style order as 0, -1, -2…. Offset it into a
  // positive local stacking range so section backgrounds cannot cover lower
  // layers while preserving the exact authored ordering.
  style.zIndex = AMP_LAYER_STACK_BASE + (node.layout.zIndex ?? -layerIndex);
  if (node.type === 'video' || node.type === 'model3d') style.background = 'transparent';
  return (
    <div
      className={`amp-runtime-node amp-runtime-node-${node.type}`}
      data-node-id={node.id}
      data-amp-text-wrap={node.type === 'model3d' ? String(node.textWrap.enabled) : undefined}
      style={style}
    >
      <RuntimeNodeContent node={node} />
    </div>
  );
});

function RuntimeNodeContent({ node }: { node: AnyNode }) {
  switch (node.type) {
    case 'text': return <RuntimeText node={node} />;
    case 'image': return <RuntimeImage node={node} />;
    case 'video': return <RuntimeVideo node={node} />;
    case 'model3d': return <RuntimeModel3D node={node} />;
    case 'audio': return <RuntimeAudio node={node} />;
    case 'divider': return <RuntimeDivider node={node} />;
    case 'spacer': return <div className="amp-runtime-spacer" aria-hidden />;
    case 'table': return <RuntimeTable node={node} />;
    case 'container': return <>{node.children.map((child, index) => <RuntimeNode key={child.id} node={child} layerIndex={index} />)}</>;
  }
}
