import type { CSSProperties } from 'react';
import type { TableNode } from '../../specification/nodes';
import { RuntimeRichText } from './RuntimeText';

export function RuntimeTable({ node }: { node: TableNode }) {
  const thin = `${node.thinBorderWidth}px solid ${node.borderColor}`;
  const thick = `${node.thickBorderWidth}px solid ${node.borderColor}`;
  const outer = node.borderTemplate === 'none' ? 'none' : node.borderTemplate === 'thin-all' ? thin : thick;
  const inner = node.borderTemplate === 'none' ? 'none' : node.borderTemplate === 'thick-all' ? thick : thin;
  return <table className="amp-runtime-table" style={{ border: outer, borderSpacing: node.cellGap, borderCollapse: node.cellGap ? 'separate' : 'collapse', background: node.backgroundColor, color: node.textColor }}><tbody>{node.rows.map((row, rowIndex) => <tr key={rowIndex} style={node.striped && rowIndex % 2 === 1 ? { background: 'color-mix(in srgb, currentColor 5%, transparent)' } : undefined}>{row.map((content, columnIndex) => {
    const header = (node.headerRow && rowIndex === 0) || (node.headerColumn && columnIndex === 0);
    const Tag = header ? 'th' : 'td';
    const style: CSSProperties = { border: inner, padding: node.cellPadding, textAlign: node.textAlign, background: header ? node.headerBackgroundColor : undefined };
    return <Tag key={columnIndex} style={style}><RuntimeRichText content={content} /></Tag>;
  })}</tr>)}</tbody></table>;
}
