import { useRuntimeContext } from '../runtime-context';

export function RuntimeCloseButton({ label, onClose }: { label: string; onClose: () => void }) {
  const { legacyMode } = useRuntimeContext();
  return <button type="button" className={`amp-runtime-close ${legacyMode.enabled ? 'legacy' : ''}`} aria-label={label} onClick={onClose}>×</button>;
}
