import { z } from 'zod';
import { baseNodeSchema } from './base';
import { assetPathSchema } from '../common/assets';

export const videoNodeSchema = baseNodeSchema.extend({
  type: z.literal('video'),
  src: assetPathSchema,
  poster: assetPathSchema.optional(),
  controls: z.boolean(),
  loop: z.boolean(),
  autoplay: z.boolean(),
  muted: z.boolean(),
  lightbox: z.object({
    enabled: z.boolean(),
    hoverLabel: z.string(),
  }).optional(),
});
export type VideoNode = z.infer<typeof videoNodeSchema>;
