import type { StaticTextWrapSpacer } from '../../specification/nodes';

export interface WrapRect {
  left: number;
  top: number;
  right: number;
  bottom: number;
  width: number;
  height: number;
}

export interface SilhouetteSource {
  id: string;
  rect: WrapRect;
  alpha: Uint8ClampedArray | null;
  alphaWidth: number;
  alphaHeight: number;
  projection?: {
    centerX: number;
    centerY: number;
    width: number;
    height: number;
    rotation: number;
  };
}

export interface SilhouetteWrapSpacer {
  id: string;
  side: 'left' | 'right';
  top: number;
  width: number;
  height: number;
  margin: number;
  shapeOutside: string;
  contour: Array<{ x: number; y: number }>;
}

interface WrapOptions {
  side: 'auto' | 'left' | 'right';
  margin: number;
  alphaThreshold: number;
  scale: number;
}

/** Unions every touching model contour into at most one float per side. */
export function buildSilhouetteWrapSpacers(
  host: WrapRect,
  sources: SilhouetteSource[],
  options: WrapOptions,
): SilhouetteWrapSpacer[] {
  const groups: Record<'left' | 'right', SilhouetteSource[]> = { left: [], right: [] };
  for (const source of sources) {
    const rect = source.rect;
    if (rect.right <= host.left || rect.left >= host.right || rect.bottom <= host.top || rect.top >= host.bottom) continue;
    const side = options.side === 'auto'
      ? ((rect.left + rect.right) / 2 <= (host.left + host.right) / 2 ? 'left' : 'right')
      : options.side;
    groups[side].push(source);
  }

  return (['left', 'right'] as const).flatMap((side) => {
    const group = groups[side];
    if (!group.length) return [];
    const top = Math.max(host.top, Math.min(...group.map((source) => source.rect.top)));
    const bottom = Math.min(host.bottom, Math.max(...group.map((source) => source.rect.bottom)));
    if (bottom <= top) return [];
    const sampleCount = Math.max(2, Math.min(128, Math.ceil((bottom - top) / Math.max(options.scale, 0.01))));
    const boundaries: number[] = [];

    for (let row = 0; row <= sampleCount; row += 1) {
      const y = top + ((bottom - top) * row) / sampleCount;
      const candidates = group
        .map((source) => scanBoundary(source, y, options.alphaThreshold, side))
        .filter((value): value is number => value !== null);
      boundaries.push(candidates.length
        ? (side === 'left' ? Math.max(...candidates) : Math.min(...candidates))
        : (side === 'left' ? host.left : host.right));
    }

    const widthPx = side === 'left'
      ? Math.max(0, Math.min(host.right, Math.max(...boundaries)) - host.left)
      : Math.max(0, host.right - Math.max(host.left, Math.min(...boundaries)));
    if (widthPx <= 0) return [];
    const scale = Math.max(options.scale, 0.01);
    const width = widthPx / scale;
    const height = (bottom - top) / scale;
    const boundaryPoints = boundaries.map((boundary, row) => {
      const y = (height * row) / sampleCount;
      const x = side === 'left'
        ? Math.max(0, Math.min(width, (boundary - host.left) / scale))
        : Math.max(0, Math.min(width, (boundary - (host.right - widthPx)) / scale));
      return { x: round(x), y: round(y) };
    });
    const contour = side === 'left'
      ? [{ x: 0, y: 0 }, ...boundaryPoints, { x: 0, y: round(height) }]
      : [{ x: round(width), y: 0 }, ...boundaryPoints, { x: round(width), y: round(height) }];
    return [{
      id: `model-silhouette-${side}`,
      side,
      top: Math.max(0, top - host.top) / scale,
      width,
      height,
      margin: options.margin,
      shapeOutside: contourToShapeOutside(contour),
      contour,
    }];
  });
}

export function bakeStaticWrapSpacers(spacers: SilhouetteWrapSpacer[]): StaticTextWrapSpacer[] {
  return spacers.map((spacer) => ({
    side: spacer.side,
    top: round(spacer.top),
    width: round(spacer.width),
    height: round(spacer.height),
    clearance: round(spacer.margin),
    contour: spacer.contour.map((point) => ({ x: round(point.x), y: round(point.y) })),
  }));
}

export function restoreStaticWrapSpacers(
  spacers: StaticTextWrapSpacer[],
  margin: number,
): SilhouetteWrapSpacer[] {
  return spacers.map((spacer) => ({
    id: `model-static-${spacer.side}`,
    side: spacer.side,
    top: spacer.top,
    width: spacer.width,
    height: spacer.height,
    margin: spacer.clearance ?? margin,
    contour: spacer.contour,
    shapeOutside: contourToShapeOutside(spacer.contour),
  }));
}

export function staticWrapSpacersEqual(a: StaticTextWrapSpacer[], b: StaticTextWrapSpacer[]) {
  return a.length === b.length && a.every((left, index) => {
    const right = b[index];
    return Boolean(right)
      && left.side === right!.side
      && left.top === right!.top
      && left.width === right!.width
      && left.height === right!.height
      && left.clearance === right!.clearance
      && left.contour.length === right!.contour.length
      && left.contour.every((point, pointIndex) => {
        const other = right!.contour[pointIndex];
        return Boolean(other) && point.x === other!.x && point.y === other!.y;
      });
  });
}

function contourToShapeOutside(contour: Array<{ x: number; y: number }>) {
  return `polygon(${contour.map((point) => `${round(point.x)}px ${round(point.y)}px`).join(', ')})`;
}

function scanBoundary(
  source: SilhouetteSource,
  y: number,
  threshold: number,
  side: 'left' | 'right',
): number | null {
  const { rect } = source;
  if (y < rect.top || y > rect.bottom || rect.width <= 0 || rect.height <= 0) return null;
  if (!source.alpha || source.alphaWidth <= 0 || source.alphaHeight <= 0) {
    return side === 'left' ? rect.right : rect.left;
  }
  if (source.projection && Math.abs(source.projection.rotation) > 0.00001) {
    return scanProjectedBoundary(source, y, threshold, side);
  }
  const row = Math.max(0, Math.min(
    source.alphaHeight - 1,
    Math.floor(((y - rect.top) / rect.height) * source.alphaHeight),
  ));
  const cutoff = Math.round(Math.max(0, Math.min(1, threshold)) * 255);
  if (side === 'left') {
    for (let x = source.alphaWidth - 1; x >= 0; x -= 1) {
      if (source.alpha[row * source.alphaWidth + x]! > cutoff) {
        return rect.left + ((x + 1) / source.alphaWidth) * rect.width;
      }
    }
  } else {
    for (let x = 0; x < source.alphaWidth; x += 1) {
      if (source.alpha[row * source.alphaWidth + x]! > cutoff) {
        return rect.left + (x / source.alphaWidth) * rect.width;
      }
    }
  }
  return null;
}

/** Pixelwise maximum used to retain every observed low-resolution pose. */
export function mergeAlphaFrames(
  previous: { alpha: Uint8ClampedArray; width: number; height: number } | null,
  next: { alpha: Uint8ClampedArray; width: number; height: number },
) {
  if (!previous || previous.width !== next.width || previous.height !== next.height) {
    return { alpha: next.alpha.slice(), width: next.width, height: next.height };
  }
  for (let index = 0; index < previous.alpha.length; index += 1) {
    if (next.alpha[index]! > previous.alpha[index]!) previous.alpha[index] = next.alpha[index]!;
  }
  return previous;
}

/** Ordered candidates: first zero-collision result is also the tightest. */
export function staticClearanceCandidates(baseline: number) {
  const offsets = [0, 1, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128];
  return Array.from(new Set(offsets.map((offset) => Math.min(200, Math.max(0, baseline + offset)))));
}

/**
 * Scores occupied low-resolution model samples that intersect laid-out text.
 * The value approximates screen-space collision area, so results remain
 * comparable across model dimensions and sampling resolutions.
 */
export function scoreSilhouetteCollisions(
  textRects: WrapRect[],
  sources: SilhouetteSource[],
  alphaThreshold: number,
) {
  const cutoff = Math.round(Math.max(0, Math.min(1, alphaThreshold)) * 255);
  let collisionArea = 0;
  for (const source of sources) {
    if (!source.alpha || source.alphaWidth <= 0 || source.alphaHeight <= 0) {
      for (const textRect of textRects) collisionArea += intersectionArea(textRect, source.rect);
      continue;
    }
    const cellArea = (source.rect.width / source.alphaWidth) * (source.rect.height / source.alphaHeight);
    for (let row = 0; row < source.alphaHeight; row += 1) {
      for (let column = 0; column < source.alphaWidth; column += 1) {
        if (source.alpha[row * source.alphaWidth + column]! <= cutoff) continue;
        const point = projectSamplePoint(source, column, row);
        if (textRects.some((rect) => point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom)) {
          collisionArea += cellArea;
        }
      }
    }
  }
  return round(collisionArea);
}

function projectSamplePoint(source: SilhouetteSource, column: number, row: number) {
  const projection = source.projection;
  if (!projection) {
    return {
      x: source.rect.left + ((column + 0.5) / source.alphaWidth) * source.rect.width,
      y: source.rect.top + ((row + 0.5) / source.alphaHeight) * source.rect.height,
    };
  }
  const localX = (((column + 0.5) / source.alphaWidth) - 0.5) * projection.width;
  const localY = (((row + 0.5) / source.alphaHeight) - 0.5) * projection.height;
  const cosine = Math.cos(projection.rotation);
  const sine = Math.sin(projection.rotation);
  return {
    x: projection.centerX + cosine * localX - sine * localY,
    y: projection.centerY + sine * localX + cosine * localY,
  };
}

function intersectionArea(left: WrapRect, right: WrapRect) {
  return Math.max(0, Math.min(left.right, right.right) - Math.max(left.left, right.left))
    * Math.max(0, Math.min(left.bottom, right.bottom) - Math.max(left.top, right.top));
}

function scanProjectedBoundary(
  source: SilhouetteSource,
  y: number,
  threshold: number,
  side: 'left' | 'right',
) {
  const projection = source.projection!;
  const { rect } = source;
  const cutoff = Math.round(Math.max(0, Math.min(1, threshold)) * 255);
  const samples = Math.max(8, Math.min(192, Math.ceil(Math.max(source.alphaWidth, rect.width))));
  const step = rect.width / samples;
  for (let sample = 0; sample < samples; sample += 1) {
    const x = side === 'left'
      ? rect.right - (sample + 0.5) * step
      : rect.left + (sample + 0.5) * step;
    if (projectedAlpha(source, projection, x, y) > cutoff) {
      return side === 'left' ? Math.min(rect.right, x + step / 2) : Math.max(rect.left, x - step / 2);
    }
  }
  return null;
}

function projectedAlpha(
  source: SilhouetteSource,
  projection: NonNullable<SilhouetteSource['projection']>,
  x: number,
  y: number,
) {
  const dx = x - projection.centerX;
  const dy = y - projection.centerY;
  const cosine = Math.cos(projection.rotation);
  const sine = Math.sin(projection.rotation);
  const localX = cosine * dx + sine * dy;
  const localY = -sine * dx + cosine * dy;
  const u = localX / projection.width + 0.5;
  const v = localY / projection.height + 0.5;
  if (u < 0 || u >= 1 || v < 0 || v >= 1) return 0;
  const column = Math.min(source.alphaWidth - 1, Math.floor(u * source.alphaWidth));
  const row = Math.min(source.alphaHeight - 1, Math.floor(v * source.alphaHeight));
  return source.alpha![row * source.alphaWidth + column] ?? 0;
}

function round(value: number) {
  return Math.round(value * 100) / 100;
}
