import { z } from 'zod';
import { baseNodeSchema } from './base';
import { assetPathSchema } from '../common/assets';

export const audioFadeSchema = z.object({
  in: z.number().min(0),
  out: z.number().min(0),
});
export type AudioFade = z.infer<typeof audioFadeSchema>;

export const audioNodeSchema = baseNodeSchema.extend({
  type: z.literal('audio'),
  src: assetPathSchema,
  loop: z.boolean(),
  volume: z.number().min(0).max(1),
  fade: audioFadeSchema.optional(),
  autoplay: z.boolean(),
  background: z.boolean().optional(),
  backgroundPlayback: z.object({
    startOnScroll: z.boolean(),
    stopAtDocumentEnd: z.boolean(),
  }).optional(),
});
export type AudioNode = z.infer<typeof audioNodeSchema>;
