const MAX_CONCURRENT_MODEL_LOADS = 2;

type Job = {
  key: string;
  start: (release: () => void) => void;
};

let active = 0;
const queued: Job[] = [];

export function enqueueRuntimeModelLoad(key: string, start: Job['start']) {
  const job = { key, start };
  if (active < MAX_CONCURRENT_MODEL_LOADS) execute(job);
  else queued.push(job);

  return () => {
    const index = queued.indexOf(job);
    if (index >= 0) queued.splice(index, 1);
  };
}

function drain() {
  while (active < MAX_CONCURRENT_MODEL_LOADS && queued.length) {
    const next = queued.shift();
    if (next) execute(next);
  }
}

function execute(job: Job) {
  active += 1;
  let released = false;
  const release = () => {
    if (released) return;
    released = true;
    active = Math.max(0, active - 1);
    drain();
  };
  try { job.start(release); }
  catch (error) { release(); throw error; }
}
