import { useEffect, useRef, useState, type RefObject } from 'react';
import type { ModelTextWrapSurface } from './use-live-model-text-wrap';

const ROOTS: Record<ModelTextWrapSurface, string> = {
  author: '.amp-canvas-viewport',
  runtime: '.amp-runtime-root',
};
const contexts = new WeakMap<HTMLCanvasElement, CanvasRenderingContext2D>();

/**
 * Uses the visible presentation bitmap as the hover target on both surfaces.
 * Transparent container space cannot pause rotation, and visibility changes
 * always clear stale hover state.
 */
export function useModelSilhouetteHover(
  track: RefObject<HTMLElement | null>,
  bitmap: RefObject<HTMLCanvasElement | null>,
  enabled: boolean,
  visible: boolean,
  surface: ModelTextWrapSurface,
) {
  const [hovered, setHovered] = useState(false);
  const current = useRef(false);

  useEffect(() => {
    const root = track.current?.closest<HTMLElement>(ROOTS[surface]);
    if (!root || !enabled || !visible) {
      current.current = false;
      return;
    }

    const update = (next: boolean) => {
      if (current.current === next) return;
      current.current = next;
      setHovered(next);
    };
    const move = (event: PointerEvent) => {
      if (event.pointerType && event.pointerType !== 'mouse' && event.pointerType !== 'pen') {
        update(false);
        return;
      }
      const canvas = bitmap.current;
      if (!canvas?.width || !canvas.height) {
        update(false);
        return;
      }
      const bounds = canvas.getBoundingClientRect();
      if (
        bounds.width <= 0 || bounds.height <= 0
        || event.clientX < bounds.left || event.clientX >= bounds.right
        || event.clientY < bounds.top || event.clientY >= bounds.bottom
      ) {
        update(false);
        return;
      }
      const x = Math.min(canvas.width - 1, Math.max(0, Math.floor((event.clientX - bounds.left) / bounds.width * canvas.width)));
      const y = Math.min(canvas.height - 1, Math.max(0, Math.floor((event.clientY - bounds.top) / bounds.height * canvas.height)));
      try {
        let context = contexts.get(canvas);
        if (!context) {
          const created = canvas.getContext('2d', { willReadFrequently: true });
          if (!created) {
            update(false);
            return;
          }
          context = created;
          contexts.set(canvas, context);
        }
        update(context.getImageData(x, y, 1, 1).data[3]! > 8);
      } catch {
        update(false);
      }
    };
    const leave = () => update(false);
    root.addEventListener('pointermove', move, { passive: true });
    root.addEventListener('pointerleave', leave, { passive: true });
    return () => {
      root.removeEventListener('pointermove', move);
      root.removeEventListener('pointerleave', leave);
      current.current = false;
      setHovered(false);
    };
  }, [bitmap, enabled, surface, track, visible]);

  return enabled && visible && hovered;
}
