import { z } from 'zod';
import { baseNodeSchema } from './base';
import { assetPathSchema } from '../common/assets';

export const imageFitSchema = z.enum(['cover', 'contain', 'fill', 'none']);
export type ImageFit = z.infer<typeof imageFitSchema>;

// Normalized (0-1) crop box relative to the source image's own dimensions,
// so crop data stays valid regardless of the original asset's resolution.
export const imageCropSchema = z.object({
  x: z.number().min(0).max(1),
  y: z.number().min(0).max(1),
  width: z.number().positive().max(1),
  height: z.number().positive().max(1),
}).superRefine((crop, context) => {
  if (crop.x + crop.width > 1) {
    context.addIssue({ code: 'custom', path: ['width'], message: 'Crop must stay within source width' });
  }
  if (crop.y + crop.height > 1) {
    context.addIssue({ code: 'custom', path: ['height'], message: 'Crop must stay within source height' });
  }
});
export type ImageCrop = z.infer<typeof imageCropSchema>;

export const imageGallerySchema = z.object({
  items: z.array(z.object({ src: assetPathSchema, alt: z.string().optional() })).min(2),
  mode: z.enum(['carousel', 'gallery']),
  autoplay: z.boolean(),
  interval: z.number().min(1).max(60),
  loop: z.boolean(),
  showArrows: z.boolean(),
  showIndicators: z.boolean(),
  transition: z.enum(['none', 'fade', 'slide']).default('fade'),
  transitionDuration: z.number().min(0.1).max(5).default(0.45),
  columns: z.number().int().min(1).max(12),
  gap: z.number().min(0).max(100),
  fullscreenView: z.boolean().default(false),
  autoAdjust: z.boolean().default(false),
}).optional();

export const imageNodeSchema = baseNodeSchema.extend({
  type: z.literal('image'),
  src: assetPathSchema,
  alt: z.string().optional(),
  fit: imageFitSchema,
  crop: imageCropSchema.optional(),
  gallery: imageGallerySchema,
});
export type ImageNode = z.infer<typeof imageNodeSchema>;
