import { useEffect, useLayoutEffect, useState, type CSSProperties, type ReactNode, type TransitionEvent } from 'react';
import { createPortal } from 'react-dom';
import type { ImageNode } from '../../specification/nodes';
import { useAMPAsset } from '../runtime-context';
import { RuntimeCloseButton } from './RuntimeLightbox';
import { useRuntimeModalClose } from './useRuntimeModalClose';

type Gallery = NonNullable<ImageNode['gallery']>;
type GalleryItem = Gallery['items'][number];

export function RuntimeImage({ node }: { node: ImageNode }) {
  const src = useAMPAsset(node.src);
  if (node.gallery) return node.gallery.mode === 'gallery' ? <GalleryView node={node} gallery={node.gallery} /> : <Carousel node={node} gallery={node.gallery} />;
  if (!src) return null;
  if (node.crop) {
    const { x, y, width, height } = node.crop;
    return <div role="img" aria-label={node.alt} className="amp-runtime-image" style={{ backgroundImage: `url(${JSON.stringify(src)})`, backgroundSize: `${100 / width}% ${100 / height}%`, backgroundPosition: `${width < 1 ? (x / (1 - width)) * 100 : 0}% ${height < 1 ? (y / (1 - height)) * 100 : 0}%` }} />;
  }
  return <img src={src} alt={node.alt ?? ''} loading="lazy" decoding="async" draggable={false} className="amp-runtime-image" style={{ objectFit: node.fit }} />;
}

function GalleryView({ node, gallery }: { node: ImageNode; gallery: Gallery }) {
  const [open, setOpen] = useState<GalleryItem>();
  const style = gallery.autoAdjust
    ? { columnCount: gallery.columns, columnGap: gallery.gap }
    : { display: 'grid', gridTemplateColumns: `repeat(${gallery.columns}, minmax(0, 1fr))`, gap: gallery.gap };
  return <>
    <div className={gallery.autoAdjust ? 'amp-runtime-gallery amp-runtime-gallery-masonry' : 'amp-runtime-gallery'} style={style}>
      {gallery.items.map((item, index) => <GalleryTile key={`${item.src}-${index}`} item={item} index={index} fit={node.fit} natural={gallery.autoAdjust} fullscreen={gallery.fullscreenView} gap={gallery.gap} onOpen={setOpen} />)}
    </div>
    {open && createPortal(<ImageLightbox item={open} onClose={() => setOpen(undefined)} />, document.body)}
  </>;
}

function GalleryTile({ item, index, fit, natural, fullscreen, gap, onOpen }: { item: GalleryItem; index: number; fit: ImageNode['fit']; natural: boolean; fullscreen: boolean; gap: number; onOpen: (item: GalleryItem) => void }) {
  const src = useAMPAsset(item.src);
  const image = src ? <img src={src} alt={item.alt ?? ''} loading="lazy" decoding="async" draggable={false} style={{ width: '100%', height: natural ? 'auto' : '100%', objectFit: fit, display: 'block' }} /> : null;
  const style: CSSProperties = { minWidth: 0, minHeight: 0, padding: 0, border: 0, display: 'block', breakInside: 'avoid', marginBottom: natural ? gap : undefined, background: 'transparent', cursor: fullscreen ? 'zoom-in' : undefined };
  return fullscreen ? <button type="button" aria-label={`View ${item.alt || `image ${index + 1}`} fullscreen`} onClick={() => onOpen(item)} style={style}>{image}</button> : <div style={style}>{image}</div>;
}

function ImageLightbox({ item, onClose }: { item: GalleryItem; onClose: () => void }) {
  const src = useAMPAsset(item.src);
  useRuntimeModalClose(onClose);
  return <div className="amp-runtime-lightbox" role="dialog" aria-label="Gallery fullscreen viewer" aria-modal="true" onContextMenu={(event) => event.preventDefault()} onDragStart={(event) => event.preventDefault()} onPointerDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    {src && <img src={src} alt={item.alt ?? ''} draggable={false} />}
    <RuntimeCloseButton label="Close image" onClose={onClose} />
  </div>;
}

function Carousel({ node, gallery }: { node: ImageNode; gallery: Gallery }) {
  const [current, setCurrent] = useState(0);
  const [transition, setTransition] = useState<{ from: number; to: number; direction: 1 | -1; running: boolean }>();
  const committed = Math.min(current, gallery.items.length - 1);
  const displayed = transition?.to ?? committed;
  const navigate = (next: number, direction: 1 | -1) => {
    if (transition || next === committed) return;
    if (gallery.transition === 'none') setCurrent(next);
    else setTransition({ from: committed, to: next, direction, running: false });
  };
  useLayoutEffect(() => {
    if (!transition || transition.running) return;
    let second = 0;
    const first = requestAnimationFrame(() => { second = requestAnimationFrame(() => setTransition((active) => active === transition ? { ...active, running: true } : active)); });
    return () => { cancelAnimationFrame(first); cancelAnimationFrame(second); };
  }, [transition]);
  useEffect(() => {
    if (!gallery.autoplay || transition) return;
    const timer = window.setTimeout(() => {
      const next = nextIndex(committed, 1, gallery.items.length, gallery.loop);
      if (next !== committed) {
        if (gallery.transition === 'none') setCurrent(next);
        else setTransition({ from: committed, to: next, direction: 1, running: false });
      }
    }, gallery.interval * 1000);
    return () => clearTimeout(timer);
  }, [committed, gallery, transition]);
  const finish = (event: TransitionEvent<HTMLDivElement>) => {
    if (event.target !== event.currentTarget || !transition?.running) return;
    if (event.propertyName !== (gallery.transition === 'fade' ? 'opacity' : 'transform')) return;
    setCurrent(transition.to); setTransition(undefined);
  };
  return <div className="amp-runtime-carousel">
    {gallery.items.map((item, index) => <Preload key={`${item.src}-${index}`} src={item.src} />)}
    {transition ? <>
      <CarouselLayer item={gallery.items[transition.from]!} fit={node.fit} gallery={gallery} direction={transition.direction} incoming={false} running={transition.running} />
      <CarouselLayer item={gallery.items[transition.to]!} fit={node.fit} gallery={gallery} direction={transition.direction} incoming running={transition.running} onTransitionEnd={finish} />
    </> : <CarouselImage item={gallery.items[committed]!} fit={node.fit} />}
    {gallery.showArrows && <><CarouselButton label="Previous image" side="left" disabled={Boolean(transition)} onClick={() => navigate(nextIndex(displayed, -1, gallery.items.length, gallery.loop), -1)}>‹</CarouselButton><CarouselButton label="Next image" side="right" disabled={Boolean(transition)} onClick={() => navigate(nextIndex(displayed, 1, gallery.items.length, gallery.loop), 1)}>›</CarouselButton></>}
    {gallery.showIndicators && <div className="amp-runtime-carousel-indicators">{gallery.items.map((_, index) => <button key={index} aria-label={`Show image ${index + 1}`} onClick={() => navigate(index, index < displayed ? -1 : 1)} className={index === displayed ? 'active' : ''} />)}</div>}
  </div>;
}

function CarouselLayer({ item, fit, gallery, direction, incoming, running, onTransitionEnd }: { item: GalleryItem; fit: ImageNode['fit']; gallery: Gallery; direction: 1 | -1; incoming: boolean; running: boolean; onTransitionEnd?: (event: TransitionEvent<HTMLDivElement>) => void }) {
  const fade = gallery.transition === 'fade';
  const offset = fade ? 0 : running ? (incoming ? 0 : -direction * 100) : (incoming ? direction * 100 : 0);
  const opacity = fade ? incoming ? (running ? 1 : 0) : (running ? 0 : 1) : 1;
  return <div className="amp-runtime-carousel-layer" aria-hidden={!incoming || undefined} onTransitionEnd={onTransitionEnd} style={{ opacity, transform: `translate3d(${offset}%,0,0)`, transition: running ? `opacity ${gallery.transitionDuration}s cubic-bezier(.22,.61,.36,1),transform ${gallery.transitionDuration}s cubic-bezier(.22,.61,.36,1)` : 'none' }}><CarouselImage item={item} fit={fit} /></div>;
}

function CarouselImage({ item, fit }: { item: GalleryItem; fit: ImageNode['fit'] }) {
  const src = useAMPAsset(item.src);
  return src ? <img src={src} alt={item.alt ?? ''} draggable={false} decoding="async" style={{ objectFit: fit }} /> : null;
}
function Preload({ src }: { src: string }) { const resolved = useAMPAsset(src); return resolved ? <link rel="preload" as="image" href={resolved} /> : null; }
function CarouselButton({ label, side, disabled, onClick, children }: { label: string; side: 'left' | 'right'; disabled: boolean; onClick: () => void; children: ReactNode }) { return <button type="button" aria-label={label} disabled={disabled} onClick={onClick} className={`amp-runtime-carousel-arrow ${side}`}>{children}</button>; }

function nextIndex(current: number, delta: number, count: number, loop: boolean) { return loop ? (current + delta + count) % count : Math.max(0, Math.min(count - 1, current + delta)); }
