import { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import type { VideoNode } from '../../specification/nodes';
import { useAMPAsset } from '../runtime-context';
import { RuntimeCloseButton } from './RuntimeLightbox';
import { useRuntimeModalClose } from './useRuntimeModalClose';

export function RuntimeVideo({ node }: { node: VideoNode }) {
  const src = useAMPAsset(node.src);
  const poster = useAMPAsset(node.poster);
  const ref = useRef<HTMLVideoElement>(null);
  const [hovered, setHovered] = useState(false);
  const [open, setOpen] = useState(false);
  const [startTime, setStartTime] = useState(0);
  const [ended, setEnded] = useState(false);
  const lightbox = node.lightbox ?? { enabled: false, hoverLabel: 'Open Fullscreen' };

  useEffect(() => {
    const video = ref.current;
    if (!video || !src || !node.autoplay) return;
    const play = () => void video.play().catch(() => undefined);
    if (typeof IntersectionObserver === 'undefined') { play(); return; }
    const observer = new IntersectionObserver(([entry]) => { if (entry?.isIntersecting) { play(); observer.disconnect(); } }, { rootMargin: '120px', threshold: 0.15 });
    observer.observe(video);
    return () => observer.disconnect();
  }, [node.autoplay, src]);
  if (!src) return null;

  const openViewer = () => {
    if (!lightbox.enabled) return;
    setStartTime(ref.current?.currentTime ?? 0);
    ref.current?.pause();
    setOpen(true);
  };
  const closeViewer = (time: number, playing: boolean) => {
    setOpen(false);
    if (!ref.current) return;
    ref.current.currentTime = time;
    if (playing && !ref.current.ended) void ref.current.play().catch(() => undefined);
  };
  const replay = () => {
    if (!ref.current) return;
    setEnded(false); ref.current.currentTime = 0; void ref.current.play().catch(() => undefined);
  };
  return <>
    <div className="amp-runtime-video" onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)} onClick={openViewer} style={{ cursor: lightbox.enabled ? 'zoom-in' : undefined }}>
      <video ref={ref} src={src} poster={poster} controls={lightbox.enabled ? false : node.controls} controlsList="nofullscreen" disablePictureInPicture loop={node.loop} muted={node.muted} playsInline preload="metadata" onPlaying={() => setEnded(false)} onEnded={() => { if (!node.loop && poster) setEnded(true); }} />
      {ended && poster && <button type="button" className="amp-runtime-video-poster" aria-label="Replay video" onClick={(event) => { event.stopPropagation(); replay(); }}><img src={poster} alt="" /></button>}
      {lightbox.enabled && <div className={`amp-runtime-video-label ${hovered ? 'visible' : ''}`}>{lightbox.hoverLabel}</div>}
    </div>
    {open && createPortal(<VideoLightbox node={node} src={src} poster={poster} initialTime={startTime} onClose={closeViewer} />, document.body)}
  </>;
}

function VideoLightbox({ node, src, poster, initialTime, onClose }: { node: VideoNode; src: string; poster?: string; initialTime: number; onClose: (time: number, playing: boolean) => void }) {
  const ref = useRef<HTMLVideoElement>(null);
  const [letterboxed, setLetterboxed] = useState(true);
  const close = useCallback(() => { const video = ref.current; onClose(video?.currentTime ?? initialTime, Boolean(video && !video.paused && !video.ended)); }, [initialTime, onClose]);
  useRuntimeModalClose(close);
  const sync = () => {
    const video = ref.current;
    if (!video) return;
    video.currentTime = Math.min(initialTime, Number.isFinite(video.duration) ? video.duration : initialTime);
    const videoAspect = video.videoWidth / Math.max(1, video.videoHeight);
    setLetterboxed(Math.abs(videoAspect - innerWidth / Math.max(1, innerHeight)) > 0.01);
    void video.play().catch(() => undefined);
  };
  return <div className="amp-runtime-lightbox" role="dialog" aria-label="Fullscreen video viewer" aria-modal="true" onContextMenu={(event) => event.preventDefault()} onDragStart={(event) => event.preventDefault()} onPointerDown={(event) => { if (event.target === event.currentTarget) close(); }} style={{ background: letterboxed ? '#000' : 'transparent' }}>
    <video ref={ref} src={src} poster={poster} draggable={false} controls={node.controls} controlsList="nofullscreen" disablePictureInPicture loop={node.loop} muted={node.muted} playsInline preload="auto" onLoadedMetadata={sync} />
    <RuntimeCloseButton label="Close video" onClose={close} />
  </div>;
}
