import { ampDocumentSchema, type AMPDocument } from './document';

export interface ValidationResult {
  success: boolean;
  document?: AMPDocument;
  errors?: string[];
}

export function validateDocument(json: unknown): ValidationResult {
  const result = ampDocumentSchema.safeParse(json);
  if (result.success) {
    return { success: true, document: result.data };
  }
  return {
    success: false,
    errors: result.error.issues.map(
      (issue) => `${issue.path.join('.') || '(root)'}: ${issue.message}`,
    ),
  };
}

export function parseDocument(json: unknown): AMPDocument {
  return ampDocumentSchema.parse(json);
}

export function serializeDocument(doc: AMPDocument): string {
  return canonicalStringify(doc);
}

export function deserializeDocument(text: string): AMPDocument {
  return parseDocument(JSON.parse(text));
}

// Sorts object keys at every level before stringifying, so a given document
// value always serializes to the same text regardless of property insertion
// order -- this is what makes Load -> Save -> Load reproduce identical output.
function canonicalStringify(value: unknown): string {
  return JSON.stringify(sortKeysDeep(value), null, 2);
}

function sortKeysDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(sortKeysDeep);
  }
  if (value !== null && typeof value === 'object') {
    const source = value as Record<string, unknown>;
    const sorted: Record<string, unknown> = {};
    for (const key of Object.keys(source).sort()) {
      sorted[key] = sortKeysDeep(source[key]);
    }
    return sorted;
  }
  return value;
}
