import { z } from 'zod';
import { baseNodeSchema } from './base';
import { richTextContentSchema } from '../common/richtext';
import { typographySchema } from '../common/typography';

export const staticTextWrapPointSchema = z.object({
  x: z.number().finite().min(0),
  y: z.number().finite().min(0),
});

export const staticTextWrapSpacerSchema = z.object({
  side: z.enum(['left', 'right']),
  top: z.number().finite().min(0),
  width: z.number().finite().min(0),
  height: z.number().finite().min(0),
  // The Author optimizer may need more separation than the user's baseline
  // margin to reach zero collision. Reader applies this resolved value.
  clearance: z.number().finite().min(0).max(200).optional(),
  contour: z.array(staticTextWrapPointSchema).min(3),
});
export type StaticTextWrapSpacer = z.infer<typeof staticTextWrapSpacerSchema>;

export const staticTextWrapBakedSchema = z.discriminatedUnion('state', [
  z.object({ state: z.literal('pending') }),
  z.object({
    state: z.literal('complete'),
    sceneSignature: z.string().min(1),
    sampleCount: z.number().int().min(1).max(96),
    collisionArea: z.number().finite().min(0),
  }),
]);
export type StaticTextWrapBaked = z.infer<typeof staticTextWrapBakedSchema>;

export const staticTextWrapSchema = z.object({
  enabled: z.boolean(),
  // Earlier strategy names remain readable because Reader renders the baked
  // contour itself. New Author saves use the collision-optimized strategy.
  strategy: z.enum(['maximum-container', 'maximum-rotation-envelope', 'iterative-collision']),
  spacers: z.array(staticTextWrapSpacerSchema).max(2),
  // Missing means a legacy baked contour. New Author documents explicitly
  // distinguish a pending bake from an atomic finalized result.
  baked: staticTextWrapBakedSchema.optional(),
});
export type StaticTextWrap = z.infer<typeof staticTextWrapSchema>;

export const runtimeTextWrapSchema = z.object({
  enabled: z.boolean(),
  // An empty list targets every overlapping Model3D node. Explicit IDs make
  // the behavior portable and deterministic when a document has many models.
  targetNodeIds: z.array(z.string()),
  side: z.enum(['auto', 'left', 'right']),
  margin: z.number().min(0).max(200),
  mode: z.enum(['container', 'silhouette']).optional(),
  alphaThreshold: z.number().min(0).max(1).optional(),
  updateFps: z.number().int().min(1).max(30).optional(),
  // Author samples low-resolution rotating silhouettes, iterates candidate
  // clearances against actual laid-out text, and persists only the winner.
  // Reader consumes the result without running the optimizer.
  static: staticTextWrapSchema.optional(),
});
export type RuntimeTextWrap = z.infer<typeof runtimeTextWrapSchema>;

export const textNodeSchema = baseNodeSchema.extend({
  type: z.literal('text'),
  content: richTextContentSchema,
  typography: typographySchema,
  runtimeWrap: runtimeTextWrapSchema.optional(),
});
export type TextNode = z.infer<typeof textNodeSchema>;
