let hiddenReaders = 0;
let legacyReaders = 0;

/** Coordinates viewport scrollbar presentation when one or more Readers mount. */
export function registerRuntimeScrollbar(legacy: boolean) {
  hiddenReaders += 1;
  if (legacy) legacyReaders += 1;
  syncClasses();

  let released = false;
  return () => {
    if (released) return;
    released = true;
    hiddenReaders = Math.max(0, hiddenReaders - 1);
    if (legacy) legacyReaders = Math.max(0, legacyReaders - 1);
    syncClasses();
  };
}

function syncClasses() {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  root.classList.toggle('amp-runtime-scrollbars-hidden', hiddenReaders > 0 && legacyReaders === 0);
  root.classList.toggle('amp-runtime-scrollbars-legacy', legacyReaders > 0);
}
