import { createContext, useContext } from 'react';
import type { LegacyMode } from '../specification/presentation';
import type { AMPAssetResolver } from './types';

export interface RuntimeContextValue {
  resolveAsset: AMPAssetResolver;
  legacyMode: LegacyMode;
}

export const RuntimeContext = createContext<RuntimeContextValue | null>(null);

export function useAMPAsset(relativePath?: string) {
  const context = useRuntimeContext();
  return relativePath ? context.resolveAsset(relativePath) : undefined;
}

export function useRuntimeContext() {
  const value = useContext(RuntimeContext);
  if (!value) throw new Error('AMP Runtime component must be rendered inside AMPReader.');
  return value;
}
