import { createRoot, type Root } from 'react-dom/client';
import { AMPReader } from './AMPReader';
import type { AMPReaderProps } from './types';

export interface MountedAMPReader {
  update(props: AMPReaderProps): void;
  unmount(): void;
}

/**
 * Framework-neutral DOM entry point. The returned controller owns only the
 * supplied host element and can be updated or unmounted by its host project.
 */
export function mountAMPReader(host: Element | string, props: AMPReaderProps): MountedAMPReader {
  const element = typeof host === 'string' ? document.querySelector(host) : host;
  if (!element) throw new Error(`AMP Reader host was not found: ${String(host)}`);
  const root: Root = createRoot(element);
  const render = (next: AMPReaderProps) => root.render(<AMPReader {...next} />);
  render(props);
  return { update: render, unmount: () => root.unmount() };
}
