import { z } from 'zod';

export const pointSchema = z.object({
  x: z.number().finite(),
  y: z.number().finite(),
});
export type Point = z.infer<typeof pointSchema>;

// 'auto' lets a dimension size to its content; Runtime resolves it during layout.
export const sizeSchema = z.object({
  width: z.union([z.number().positive().finite(), z.literal('auto')]),
  height: z.union([z.number().positive().finite(), z.literal('auto')]),
});
export type Size = z.infer<typeof sizeSchema>;

export const boxSpacingSchema = z.object({
  top: z.number().finite(),
  right: z.number().finite(),
  bottom: z.number().finite(),
  left: z.number().finite(),
});
export type BoxSpacing = z.infer<typeof boxSpacingSchema>;
