import { useEffect, useRef, type MutableRefObject } from 'react';
import type { AudioNode } from '../../specification/nodes';
import { useAMPAsset } from '../runtime-context';

export function RuntimeAudio({ node }: { node: AudioNode }) {
  const src = useAMPAsset(node.src);
  const ref = useRef<HTMLAudioElement>(null);
  const fadeFrame = useRef(0);
  const stoppedAtEnd = useRef(false);

  useEffect(() => { if (ref.current) ref.current.volume = node.volume; }, [node.volume]);
  useEffect(() => {
    if (!node.background) return;
    const activeFade = fadeFrame;
    const behavior = node.backgroundPlayback ?? { startOnScroll: true, stopAtDocumentEnd: true };
    const start = (event: WheelEvent) => {
      if (!behavior.startOnScroll || event.deltaY <= 0 || stoppedAtEnd.current) return;
      const audio = ref.current;
      if (!audio || !audio.paused) return;
      audio.volume = node.fade?.in ? 0 : node.volume;
      void audio.play().then(() => animateVolume(audio, node.volume, node.fade?.in ?? 0, fadeFrame)).catch(() => undefined);
    };
    const detectEnd = () => {
      if (!behavior.stopAtDocumentEnd || stoppedAtEnd.current) return;
      const root = ref.current?.closest<HTMLElement>('.amp-runtime-root');
      if (!root || root.getBoundingClientRect().bottom > innerHeight + 2) return;
      const audio = ref.current;
      if (!audio || audio.paused) return;
      stoppedAtEnd.current = true;
      animateVolume(audio, 0, node.fade?.out ?? 0, fadeFrame, () => audio.pause());
    };
    window.addEventListener('wheel', start, { passive: true });
    window.addEventListener('scroll', detectEnd, { passive: true });
    return () => { window.removeEventListener('wheel', start); window.removeEventListener('scroll', detectEnd); cancelAnimationFrame(activeFade.current); };
  }, [node.background, node.backgroundPlayback, node.fade, node.volume]);
  if (!src) return null;

  const applyMediaFade = () => {
    const audio = ref.current;
    if (!audio || stoppedAtEnd.current) return;
    const fadeIn = node.fade?.in ?? 0;
    const fadeOut = node.fade?.out ?? 0;
    const incoming = fadeIn ? Math.min(1, audio.currentTime / fadeIn) : 1;
    const remaining = Number.isFinite(audio.duration) ? audio.duration - audio.currentTime : Infinity;
    const outgoing = fadeOut ? Math.min(1, Math.max(0, remaining / fadeOut)) : 1;
    audio.volume = node.volume * Math.min(incoming, outgoing);
  };
  return <audio ref={ref} src={src} controls={!node.background} loop={node.loop} autoPlay={!node.background && node.autoplay} preload="metadata" onPlay={applyMediaFade} onTimeUpdate={applyMediaFade} style={{ width: '100%', display: node.background ? 'none' : 'block' }} />;
}

function animateVolume(audio: HTMLAudioElement, target: number, seconds: number, frame: MutableRefObject<number>, done?: () => void) {
  cancelAnimationFrame(frame.current);
  if (!seconds) { audio.volume = target; done?.(); return; }
  const startVolume = audio.volume;
  const started = performance.now();
  const tick = (now: number) => {
    const progress = Math.min(1, (now - started) / (seconds * 1000));
    audio.volume = startVolume + (target - startVolume) * progress;
    if (progress < 1) frame.current = requestAnimationFrame(tick); else done?.();
  };
  frame.current = requestAnimationFrame(tick);
}
