import { z } from 'zod';

export type JSONValue = string | number | boolean | null | JSONValue[] | { [key: string]: JSONValue };

// Extension metadata is deliberately supported, but AMP is a JSON format:
// values such as bigint, Date, functions, undefined, NaN and Infinity must
// be rejected before save rather than silently changing during stringify.
export const jsonValueSchema: z.ZodType<JSONValue> = z.lazy(() => z.union([
  z.string(),
  z.number().finite(),
  z.boolean(),
  z.null(),
  z.array(jsonValueSchema),
  z.record(z.string(), jsonValueSchema),
]));
