import { z } from 'zod';
import { baseNodeSchema } from './base';
import { richTextContentSchema } from '../common/richtext';
import type { RichTextContent } from '../common/richtext';

export const tableBorderTemplateSchema = z.enum([
  'none',
  'thin-all',
  'thick-all',
  'thick-outside-thin-inside',
]);

// Legacy v1 tables stored plain strings. Parsing upgrades them into the same
// rich-text model used by Text nodes; canonical saves emit only rich content.
export const tableCellContentSchema = z.union([
  richTextContentSchema,
  z.string().transform((text): RichTextContent => [{
    kind: 'paragraph' as const,
    runs: text ? [{ text }] : [],
  }]),
]);

export const tableNodeSchema = baseNodeSchema.extend({
  type: z.literal('table'),
  rows: z.array(z.array(tableCellContentSchema).min(1)).min(1),
  headerRow: z.boolean(),
  headerColumn: z.boolean(),
  borderTemplate: tableBorderTemplateSchema,
  borderColor: z.string(),
  thinBorderWidth: z.number().min(0.25).max(10),
  thickBorderWidth: z.number().min(1).max(20),
  cellPadding: z.number().min(0).max(100),
  cellGap: z.number().min(0).max(50),
  textColor: z.string(),
  backgroundColor: z.string(),
  headerBackgroundColor: z.string(),
  striped: z.boolean(),
  textAlign: z.enum(['left', 'center', 'right']),
}).superRefine((table, context) => {
  const columns = table.rows[0]?.length ?? 0;
  table.rows.forEach((row, index) => {
    if (row.length !== columns) context.addIssue({ code: 'custom', path: ['rows', index], message: 'Every table row must have the same number of columns' });
  });
});

export type TableNode = z.infer<typeof tableNodeSchema>;
