import { z } from 'zod';
import { baseNodeSchema } from './base';
import { assetPathSchema } from '../common/assets';

export const lightingPresetSchema = z.enum(['studio', 'soft', 'dramatic', 'neutral', 'outdoor']);
export type LightingPreset = z.infer<typeof lightingPresetSchema>;

export const environmentPresetSchema = z.enum([
  'none',
  'studio',
  'sunset',
  'dawn',
  'night',
  'warehouse',
  'forest',
  'apartment',
  'city',
  'park',
  'lobby',
]);
export type EnvironmentPreset = z.infer<typeof environmentPresetSchema>;

export const shadowOptionSchema = z.enum(['none', 'soft', 'hard']);
export type ShadowOption = z.infer<typeof shadowOptionSchema>;

export const model3DBehaviorsSchema = z.object({
  autoRotate: z.boolean(),
  pauseOnHover: z.boolean(),
  resumeOnLeave: z.boolean(),
  rotationOffset: z.object({
    enabled: z.boolean(),
    x: z.number().min(-360).max(360),
    y: z.number().min(-360).max(360),
    z: z.number().min(-360).max(360),
  }).optional(),
  // Degrees per second. A value of zero locks that axis during auto-rotation.
  rotationSpeed: z.object({
    x: z.number().min(-360).max(360),
    y: z.number().min(-360).max(360),
    z: z.number().min(-360).max(360),
  }).optional(),
});
export type Model3DBehaviors = z.infer<typeof model3DBehaviorsSchema>;

export const model3DCameraSchema = z.object({
  fov: z.number().min(10).max(120),
});
export type Model3DCamera = z.infer<typeof model3DCameraSchema>;

export const model3DToonSchema = z.object({
  enabled: z.boolean(),
  bands: z.number().int().min(2).max(8),
  strength: z.number().min(0).max(1),
  smoothness: z.number().min(0).max(0.49),
  roughnessMultiplier: z.number().min(0).max(2),
  metalnessMultiplier: z.number().min(0).max(2),
  opacityMultiplier: z.number().min(0).max(1),
  normalScale: z.number().min(0).max(2),
  ao: z.object({
    enabled: z.boolean(),
    intensity: z.number().min(0).max(2),
  }).optional(),
  outline: z.object({
    enabled: z.boolean(),
    color: z.string(),
    thickness: z.number().min(0).max(0.1),
    opacity: z.number().min(0).max(1),
  }).optional(),
});
export type Model3DToon = z.infer<typeof model3DToonSchema>;

export const model3DMaterialOverrideSchema = z.object({
  enabled: z.boolean(),
  baseColor: z.string(),
  roughness: z.number().min(0).max(1),
  metalness: z.number().min(0).max(1),
});
export type Model3DMaterialOverride = z.infer<typeof model3DMaterialOverrideSchema>;

export const model3DWireframeSchema = z.object({
  enabled: z.boolean(),
  color: z.string(),
  // Screen-space pixels. Runtime uses wide-line geometry because WebGL's
  // native lineWidth is effectively fixed to one pixel on most platforms.
  thickness: z.number().min(0.5).max(8),
});
export type Model3DWireframe = z.infer<typeof model3DWireframeSchema>;

export const model3DTextWrapSchema = z.object({
  enabled: z.boolean(),
});
export type Model3DTextWrap = z.infer<typeof model3DTextWrapSchema>;

// Runtime imports GLB/GLTF with Blender's Z-up convention remapped to
// WebGL's Y-up; that axis swap is a fixed Runtime rule, not authored data.
export const model3DNodeSchema = baseNodeSchema.extend({
  type: z.literal('model3d'),
  src: assetPathSchema,
  behaviors: model3DBehaviorsSchema,
  camera: model3DCameraSchema.optional(),
  toon: model3DToonSchema.optional(),
  materialOverride: model3DMaterialOverrideSchema.optional(),
  wireframe: model3DWireframeSchema.optional(),
  // Per-model participation is authoritative even when a Text node targets
  // this model explicitly. Default true preserves v1 documents authored
  // before this switch existed and makes the next save canonical.
  textWrap: model3DTextWrapSchema.default({ enabled: true }),
  lighting: lightingPresetSchema.optional(),
  lightingIntensity: z.number().min(0).max(5).optional(),
  environment: environmentPresetSchema.optional(),
  shadows: shadowOptionSchema.optional(),
  // When disabled, both sides of every surface are rendered. Keeping this
  // explicit also makes silhouette-driven text flow deterministic.
  backfaceCulling: z.boolean().optional(),
  // v1 legacy documents may contain false. Normalize it during parsing so
  // the canonical document and every renderer agree that model containers
  // are transparent without making older projects unloadable.
  transparentBackground: z.boolean().optional().transform(() => true),
});
export type Model3DNode = z.infer<typeof model3DNodeSchema>;
