import { parseDocument, type AMPDocument } from '../specification';
import type { LoadedAMPDocument } from './types';

export async function loadAMPDocument(
  source: string | URL | AMPDocument | unknown,
  options: { signal?: AbortSignal; fetcher?: typeof fetch } = {},
): Promise<LoadedAMPDocument> {
  if (source instanceof URL) return fetchDocument(source.toString(), options);
  if (typeof source === 'string') {
    const trimmed = source.trim();
    if (trimmed.startsWith('{')) return { document: parseDocument(JSON.parse(trimmed)) };
    return fetchDocument(source, options);
  }
  return { document: parseDocument(source) };
}

async function fetchDocument(url: string, options: { signal?: AbortSignal; fetcher?: typeof fetch }) {
  const request = options.fetcher ?? fetch;
  const response = await request(url, { signal: options.signal, credentials: 'same-origin' });
  if (!response.ok) throw new Error(`Unable to load AMP document (${response.status} ${response.statusText}).`);
  let json: unknown;
  try { json = await response.json(); }
  catch { throw new Error('The AMP document response is not valid JSON.'); }
  const responseUrl = response.url || new URL(url, globalThis.location?.href ?? 'http://amp.local/').toString();
  return {
    document: parseDocument(json),
    inferredAssetBaseUrl: new URL('.', responseUrl).toString(),
  };
}

export function createAMPAssetResolver(baseUrl: string | URL): (relativePath: string) => string {
  const base = new URL(baseUrl.toString(), globalThis.location?.href ?? 'http://amp.local/');
  return (relativePath) => relativePath ? new URL(relativePath, base).toString() : '';
}
