import { useRef, type CSSProperties, type ReactNode } from 'react';
import type { RichTextContent, TextRun } from '../../specification/common/richtext';
import type { TextNode } from '../../specification/nodes';
import { useLiveModelTextWrap } from '../../rendering/use-live-model-text-wrap';

export function RuntimeText({ node }: { node: TextNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const spacers = useLiveModelTextWrap(ref, node, 'runtime');
  const typography = node.typography;
  return <div ref={ref} className="amp-runtime-text" style={{
    fontFamily: typography.fontFamily,
    fontSize: typography.fontSize,
    fontWeight: typography.fontWeight,
    fontStyle: typography.fontStyle,
    color: typography.color,
    letterSpacing: typography.letterSpacing,
    lineHeight: typography.lineHeight,
    textAlign: typography.justify,
    textIndent: typography.indent,
    display: 'flow-root',
  }}>
    {spacers.map((spacer) => <span key={spacer.id} aria-hidden style={{ display: 'block', float: spacer.side, width: spacer.width, height: spacer.height, marginTop: spacer.top, shapeOutside: spacer.shapeOutside, shapeMargin: `${spacer.margin}px`, pointerEvents: 'none' }} />)}
    <RuntimeRichText content={node.content} paragraphSpacing={typography.paragraphSpacing} />
  </div>;
}

export function RuntimeRichText({ content, paragraphSpacing }: { content: RichTextContent; paragraphSpacing?: number }) {
  const rendered: ReactNode[] = [];
  for (let index = 0; index < content.length;) {
    const block = content[index]!;
    if (!block.listType || block.listType === 'none') {
      rendered.push(<p key={index} style={{ margin: 0, marginBottom: paragraphSpacing, marginLeft: block.indent ? block.indent * 24 : undefined }}>{block.runs.map(renderRun)}</p>);
      index += 1;
      continue;
    }
    const listType = block.listType;
    const start = index;
    const items: ReactNode[] = [];
    while (index < content.length && content[index]!.listType === listType) {
      const item = content[index]!;
      items.push(<li key={index} style={{ marginBottom: paragraphSpacing, marginLeft: item.indent ? item.indent * 24 : undefined }}>{item.runs.map(renderRun)}</li>);
      index += 1;
    }
    const listStyle: CSSProperties = { margin: 0, paddingLeft: 24 };
    rendered.push(listType === 'ordered' ? <ol key={start} style={listStyle}>{items}</ol> : <ul key={start} style={listStyle}>{items}</ul>);
  }
  return <>{rendered}</>;
}

function renderRun(run: TextRun, index: number) {
  const marks = run.marks ?? [];
  const decorations = [marks.includes('underline') ? 'underline' : '', marks.includes('strikethrough') ? 'line-through' : ''].filter(Boolean).join(' ');
  const style: CSSProperties = { color: run.color, fontWeight: marks.includes('bold') ? 'bold' : undefined, fontStyle: marks.includes('italic') ? 'italic' : undefined, textDecoration: decorations || undefined };
  // A classed span avoids inheriting host-site `code` backgrounds when the
  // Reader module is embedded externally. The code mark remains authoritative
  // in JSON while Reader only changes its font presentation.
  const content = marks.includes('code') ? <span className="amp-runtime-code">{run.text}</span> : run.text;
  const href = safeHref(run.href);
  return href ? <a key={index} href={href} style={style}>{content}</a> : <span key={index} style={style}>{content}</span>;
}

function safeHref(href?: string) {
  if (!href) return undefined;
  if (href.startsWith('#') || href.startsWith('/') || href.startsWith('./') || href.startsWith('../')) return href;
  try {
    const protocol = new URL(href).protocol;
    return ['http:', 'https:', 'mailto:', 'tel:'].includes(protocol) ? href : undefined;
  } catch { return undefined; }
}
