import { z } from 'zod';

// Author and Runtime resolve assets from the project root. Empty is allowed
// while a new node is being authored, but any non-empty value must be a
// normalized, portable relative path (never a URL, drive path, or traversal).
export const assetPathSchema = z.string().refine(
  (path) => {
    if (path === '') return true;
    if (path.includes('\\') || path.startsWith('/') || /^[a-z][a-z\d+.-]*:/i.test(path)) {
      return false;
    }
    const parts = path.split('/');
    return parts.every((part) => part.length > 0 && part !== '.' && part !== '..');
  },
  'Asset reference must be a normalized relative project path',
);
