import { useEffect, useMemo, useState } from 'react';
import { createDefaultDocumentPresentation } from '../specification/presentation';
import { RuntimeContext } from './runtime-context';
import { createAMPAssetResolver, loadAMPDocument } from './load';
import { RuntimeDocument } from './RuntimeDocument';
import type { AMPReaderProps, LoadedAMPDocument } from './types';
import './runtime.css';

export function AMPReader({
  document: documentInput,
  src,
  assetBaseUrl,
  resolveAsset,
  className,
  style,
  loadingFallback,
  errorFallback,
  onLoad,
  onError,
  ariaLabel,
}: AMPReaderProps) {
  const [state, setState] = useState<{ loaded?: LoadedAMPDocument; error?: Error }>({});
  const missingSource = documentInput === undefined && src === undefined
    ? new Error('AMPReader requires either a document or src.')
    : undefined;

  useEffect(() => {
    if (documentInput === undefined && src === undefined) return;
    const controller = new AbortController();
    loadAMPDocument(documentInput ?? src!, { signal: controller.signal }).then((loaded) => {
      if (controller.signal.aborted) return;
      setState({ loaded });
      onLoad?.(loaded.document);
    }).catch((caught: unknown) => {
      if (controller.signal.aborted) return;
      const error = caught instanceof Error ? caught : new Error(String(caught));
      setState({ error });
      onError?.(error);
    });
    return () => controller.abort();
  }, [documentInput, onError, onLoad, src]);

  const resolver = useMemo(() => {
    if (resolveAsset) return resolveAsset;
    const base = assetBaseUrl ?? state.loaded?.inferredAssetBaseUrl ?? globalThis.location?.href ?? '/';
    return createAMPAssetResolver(base);
  }, [assetBaseUrl, resolveAsset, state.loaded?.inferredAssetBaseUrl]);

  const error = missingSource ?? state.error;
  if (error) {
    return <div className={`amp-runtime-error ${className ?? ''}`} style={style} role="alert">
      {errorFallback?.(error) ?? <><strong>Unable to open AMP document</strong><span>{error.message}</span></>}
    </div>;
  }
  if (!state.loaded) return <>{loadingFallback ?? <div className={`amp-runtime-loading ${className ?? ''}`} style={style}>Loading AMP document…</div>}</>;

  const presentation = state.loaded.document.presentation ?? createDefaultDocumentPresentation();
  return (
    <RuntimeContext.Provider value={{ resolveAsset: resolver, legacyMode: presentation.legacyMode }}>
      <RuntimeDocument document={state.loaded.document} className={className} style={style} ariaLabel={ariaLabel} />
    </RuntimeContext.Provider>
  );
}
