import { z } from 'zod';

/**
 * Reader-facing presentation settings. These are document data, never local
 * preferences: a Reader must reproduce the same first-load treatment that was
 * selected in Author.
 */
export const loadPixelationSchema = z.object({
  enabled: z.boolean(),
  trigger: z.literal('document-load'),
  duration: z.number().min(100).max(10_000),
  disruption: z.number().min(0).max(1),
  blur: z.number().min(0).max(64),
});
export type LoadPixelation = z.infer<typeof loadPixelationSchema>;

export const legacyModeSchema = z.object({
  enabled: z.boolean(),
  pixelation: loadPixelationSchema,
});
export type LegacyMode = z.infer<typeof legacyModeSchema>;

export const documentPresentationSchema = z.object({
  legacyMode: legacyModeSchema,
});
export type DocumentPresentation = z.infer<typeof documentPresentationSchema>;

export const DEFAULT_DOCUMENT_PRESENTATION: DocumentPresentation = {
  legacyMode: {
    enabled: false,
    pixelation: {
      enabled: true,
      trigger: 'document-load',
      duration: 2_000,
      disruption: 0.75,
      blur: 22,
    },
  },
};

export function createDefaultDocumentPresentation(): DocumentPresentation {
  return {
    legacyMode: {
      ...DEFAULT_DOCUMENT_PRESENTATION.legacyMode,
      pixelation: { ...DEFAULT_DOCUMENT_PRESENTATION.legacyMode.pixelation },
    },
  };
}
