export interface VisibilityRect {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

export function sectionClipsModelVisibility(overflow: string | undefined) {
  return overflow !== 'visible';
}

/**
 * Tests the model against the real viewport and every clipping ancestor.
 * IntersectionObserver can retain a stale result while AMP's responsive stage
 * is transformed or programmatically scrolled, so animation culling uses this
 * deterministic geometry check.
 */
export function isModelActuallyVisible(
  model: VisibilityRect,
  viewport: VisibilityRect,
  clippingAncestors: VisibilityRect[],
) {
  let left = viewport.left;
  let top = viewport.top;
  let right = viewport.right;
  let bottom = viewport.bottom;
  for (const clip of clippingAncestors) {
    left = Math.max(left, clip.left);
    top = Math.max(top, clip.top);
    right = Math.min(right, clip.right);
    bottom = Math.min(bottom, clip.bottom);
  }
  return right > left
    && bottom > top
    && model.right > left
    && model.left < right
    && model.bottom > top
    && model.top < bottom;
}
