import { lazy, Suspense, useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties } from 'react';
import type { AMPDocument, Section } from '../specification';
import { AMP_REFERENCE_CANVAS_WIDTH } from '../specification/canvas';
import type { AnyNode } from '../specification/nodes';
import { useAMPAsset, useRuntimeContext } from './runtime-context';
import { RuntimeNode } from './RuntimeNode';
import { registerRuntimeScrollbar } from './scrollbar-mode';

const RuntimeModel3DStage = lazy(() => import('./model3d/RuntimeModel3DStage'));

export function RuntimeDocument({ document, className, style, ariaLabel }: {
  document: AMPDocument;
  className?: string;
  style?: CSSProperties;
  ariaLabel?: string;
}) {
  const hostRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const initialHeight = useMemo(() => document.sections.reduce((total, section) => total + (typeof section.height === 'number' ? section.height : AMP_REFERENCE_CANVAS_WIDTH), 0), [document.sections]);
  const [dimensions, setDimensions] = useState({ scale: 1, height: initialHeight });
  const hasModels = useMemo(() => inspectModels(document), [document]);
  const legacyEnabled = document.presentation?.legacyMode.enabled ?? false;

  useEffect(() => registerRuntimeScrollbar(legacyEnabled), [legacyEnabled]);

  useLayoutEffect(() => {
    const host = hostRef.current;
    const stage = stageRef.current;
    if (!host || !stage) return;
    let frame = 0;
    const measure = () => {
      frame = 0;
      const width = host.clientWidth || AMP_REFERENCE_CANVAS_WIDTH;
      const scale = width / AMP_REFERENCE_CANVAS_WIDTH;
      const height = Math.max(initialHeight, stage.scrollHeight);
      setDimensions((current) => current.scale === scale && current.height === height ? current : { scale, height });
    };
    const schedule = () => { if (!frame) frame = requestAnimationFrame(measure); };
    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(schedule);
    observer?.observe(host);
    observer?.observe(stage);
    window.addEventListener('resize', schedule);
    schedule();
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', schedule);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [initialHeight]);

  return (
    <div
      ref={hostRef}
      className={`amp-runtime-root ${document.presentation?.legacyMode.enabled ? 'amp-runtime-legacy' : ''} ${className ?? ''}`}
      style={{ ...style, height: dimensions.height * dimensions.scale }}
      role="region"
      aria-label={ariaLabel ?? document.metadata.title ?? 'AMP document'}
      data-amp-version={document.version}
      onContextMenu={(event) => event.preventDefault()}
      onDragStart={(event) => event.preventDefault()}
    >
      <RuntimeFonts document={document} />
      <div
        ref={stageRef}
        className="amp-runtime-stage"
        style={{ width: AMP_REFERENCE_CANVAS_WIDTH, transform: `scale(${dimensions.scale})` }}
      >
        {document.sections.map((section) => <RuntimeSection key={section.id} section={section} />)}
      </div>
      {hasModels && (
        <Suspense fallback={null}>
          <RuntimeModel3DStage />
        </Suspense>
      )}
      <RuntimeLoadPresentation document={document} />
    </div>
  );
}

function RuntimeSection({ section }: { section: Section }) {
  const background = useAMPAsset(section.background?.image);
  const overflow = section.overflow ?? 'hidden';
  return (
    <section
      className="amp-runtime-section"
      data-section-id={section.id}
      data-amp-section-overflow={overflow}
      aria-label={section.name}
      style={{
        minHeight: typeof section.height === 'number' ? section.height : AMP_REFERENCE_CANVAS_WIDTH,
        backgroundColor: section.background?.color,
        backgroundImage: background ? `url(${JSON.stringify(background)})` : undefined,
        overflow,
        isolation: overflow === 'hidden' ? 'isolate' : 'auto',
      }}
    >
      {section.nodes.map((node, index) => <RuntimeNode key={node.id} node={node} layerIndex={index} />)}
    </section>
  );
}

function RuntimeFonts({ document }: { document: AMPDocument }) {
  const { resolveAsset } = useRuntimeContext();
  const rules = (document.fonts ?? []).map((font) => {
    const source = resolveAsset(font.src);
    return `@font-face{font-family:${JSON.stringify(font.family)};src:url(${JSON.stringify(source)});font-weight:${font.weight ?? 'normal'};font-style:${font.style ?? 'normal'};font-display:swap}`;
  });
  return rules.length ? <style>{rules.join('\n')}</style> : null;
}

function RuntimeLoadPresentation({ document }: { document: AMPDocument }) {
  const legacy = document.presentation?.legacyMode;
  if (!legacy?.enabled || !legacy.pixelation.enabled) return null;
  return <RuntimePixelation key={document.metadata.id} settings={legacy.pixelation} />;
}

function RuntimePixelation({ settings }: { settings: AMPDocument['presentation']['legacyMode']['pixelation'] }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    let cleanup: (() => void) | undefined;
    const frame = requestAnimationFrame(() => {
      void import('../author/legacy/mosaic-reveal').then(({ runMosaicReveal }) => {
        cleanup = runMosaicReveal(root, settings);
      });
    });
    return () => { cancelAnimationFrame(frame); cleanup?.(); };
  }, [settings]);
  return <div ref={ref} className="amp-compositor" aria-hidden><div className="amp-compositor-backdrop" data-amp-backdrop /><canvas className="amp-compositor-mosaic" /><div className="amp-compositor-scanlines" data-amp-scanlines /><div className="amp-compositor-vignette" data-amp-vignette /></div>;
}

function inspectModels(document: AMPDocument) {
  let hasModels = false;
  const visit = (nodes: AnyNode[]) => nodes.forEach((node) => {
    if (node.type === 'model3d') hasModels = true;
    else if (node.type === 'container') visit(node.children);
  });
  document.sections.forEach((section) => visit(section.nodes));
  return hasModels;
}
