import { z } from 'zod';
import { nodeLayoutSchema } from '../common/layout';
import { jsonValueSchema } from '../common/json';

// catchall keeps forward-compat: renderers/future node types can carry extra
// style fields without failing validation against an older spec version.
export const nodeStyleSchema = z
  .object({
    opacity: z.number().min(0).max(1).optional(),
    backgroundColor: z.string().optional(),
    borderRadius: z.number().min(0).finite().optional(),
    border: z
      .object({
        width: z.number().min(0).finite(),
        color: z.string(),
        style: z.enum(['solid', 'dashed', 'dotted']).optional(),
      })
      .optional(),
  })
  .catchall(jsonValueSchema);
export type NodeStyle = z.infer<typeof nodeStyleSchema>;

export const baseNodeSchema = z.object({
  id: z.string().min(1),
  type: z.string(),
  name: z.string().optional(),
  layout: nodeLayoutSchema,
  style: nodeStyleSchema.optional(),
  metadata: z.record(z.string(), jsonValueSchema).optional(),
});
export type BaseNode = z.infer<typeof baseNodeSchema>;
