import type { CSSProperties } from 'react';
import type { Anchor, NodeLayout } from '../specification/common/layout';
import type { NodeStyle } from '../specification/nodes/base';

const ANCHOR_OFFSETS: Record<Anchor, [number, number]> = {
  'top-left': [0, 0], 'top-center': [0.5, 0], 'top-right': [1, 0],
  'center-left': [0, 0.5], center: [0.5, 0.5], 'center-right': [1, 0.5],
  'bottom-left': [0, 1], 'bottom-center': [0.5, 1], 'bottom-right': [1, 1],
};

export function runtimeLayoutStyle(layout: NodeLayout, style?: NodeStyle): CSSProperties {
  const css: CSSProperties = { boxSizing: 'border-box', position: 'relative' };
  const width = layout.size.width;
  const height = layout.size.height;
  if (width !== 'auto') css.width = width;
  if (height !== 'auto') css.height = height;
  applySpacing(css, 'margin', layout.margin);
  applySpacing(css, 'padding', layout.padding);

  if (layout.mode === 'absolute') {
    css.position = 'absolute';
    const [anchorX, anchorY] = ANCHOR_OFFSETS[layout.anchor ?? 'top-left'];
    css.left = (layout.position?.x ?? 0) - (width === 'auto' ? 0 : width * anchorX);
    css.top = (layout.position?.y ?? 0) - (height === 'auto' ? 0 : height * anchorY);
  } else if (layout.mode === 'float-left') css.float = 'left';
  else if (layout.mode === 'float-right') css.float = 'right';
  else if (layout.mode === 'inline') css.display = 'inline-block';
  else if (layout.mode === 'center') {
    css.display = 'block';
    css.marginLeft ??= 'auto';
    css.marginRight ??= 'auto';
  }

  if (layout.align) css.textAlign = layout.align;
  if (layout.rotation) { css.transform = `rotate(${layout.rotation}deg)`; css.transformOrigin = 'center center'; }
  if (layout.zIndex !== undefined) css.zIndex = layout.zIndex;
  if (layout.overflow) css.overflow = layout.overflow;
  if (style?.opacity !== undefined) css.opacity = style.opacity;
  if (style?.backgroundColor) css.backgroundColor = style.backgroundColor;
  if (style?.borderRadius !== undefined) css.borderRadius = style.borderRadius;
  if (style?.border) {
    css.borderStyle = style.border.style ?? 'solid';
    css.borderWidth = style.border.width;
    css.borderColor = style.border.color;
  }
  return css;
}

function applySpacing(css: CSSProperties, prefix: 'margin' | 'padding', spacing?: Partial<Record<'top' | 'right' | 'bottom' | 'left', number>>) {
  if (!spacing) return;
  for (const side of ['top', 'right', 'bottom', 'left'] as const) {
    const value = spacing[side];
    if (value !== undefined) (css as Record<string, unknown>)[`${prefix}${side[0]!.toUpperCase()}${side.slice(1)}`] = value;
  }
}
