import { z } from 'zod';

export const textMarkSchema = z.enum(['bold', 'italic', 'underline', 'strikethrough', 'code']);
export type TextMark = z.infer<typeof textMarkSchema>;

export const textRunSchema = z.object({
  text: z.string(),
  marks: z.array(textMarkSchema).optional(),
  color: z.string().optional(),
  href: z.string().optional(),
});
export type TextRun = z.infer<typeof textRunSchema>;

export const listTypeSchema = z.enum(['none', 'ordered', 'unordered']);
export type ListType = z.infer<typeof listTypeSchema>;

export const paragraphBlockSchema = z.object({
  kind: z.literal('paragraph'),
  runs: z.array(textRunSchema),
  listType: listTypeSchema.optional(),
  indent: z.number().int().optional(),
});
export type ParagraphBlock = z.infer<typeof paragraphBlockSchema>;

export const richTextContentSchema = z.array(paragraphBlockSchema);
export type RichTextContent = z.infer<typeof richTextContentSchema>;
