import { z } from 'zod';
import { nodeSchema, type AnyNode } from './nodes';
import { assetPathSchema } from './common/assets';
import { AMP_SPEC_VERSION } from './version';
import { jsonValueSchema } from './common/json';
import { createDefaultDocumentPresentation, documentPresentationSchema } from './presentation';

export const fontAssetSchema = z.object({
  family: z.string(),
  src: assetPathSchema,
  weight: z.union([z.number().int(), z.enum(['normal', 'bold'])]).optional(),
  style: z.enum(['normal', 'italic']).optional(),
});
export type FontAsset = z.infer<typeof fontAssetSchema>;

export const documentMetadataSchema = z
  .object({
    id: z.string().min(1),
    title: z.string().optional(),
    createdAt: z.string().optional(),
    updatedAt: z.string().optional(),
    author: z.string().optional(),
  })
  .catchall(jsonValueSchema);
export type DocumentMetadata = z.infer<typeof documentMetadataSchema>;

export const sectionBackgroundSchema = z.object({
  color: z.string().optional(),
  image: assetPathSchema.optional(),
});
export type SectionBackground = z.infer<typeof sectionBackgroundSchema>;

export const sectionOverflowSchema = z.enum(['hidden', 'visible']);
export type SectionOverflow = z.infer<typeof sectionOverflowSchema>;

export const sectionSchema = z.object({
  id: z.string().min(1),
  name: z.string().optional(),
  height: z.union([z.number().positive(), z.literal('auto')]).optional(),
  // The section boundary clips authored layers by default. Making the value
  // explicit during parsing keeps Author and Reader behavior deterministic
  // for legacy documents as well as newly created projects.
  overflow: sectionOverflowSchema.default('hidden'),
  background: sectionBackgroundSchema.optional(),
  nodes: z.array(nodeSchema),
});
export type Section = z.infer<typeof sectionSchema>;

export const ampDocumentSchema = z.object({
  version: z.literal(AMP_SPEC_VERSION),
  metadata: documentMetadataSchema,
  // Legacy v1 documents load with explicit deterministic presentation data,
  // so their next canonical save fully describes Reader first-load behavior.
  presentation: documentPresentationSchema.default(createDefaultDocumentPresentation),
  fonts: z.array(fontAssetSchema).optional(),
  sections: z.array(sectionSchema).min(1),
}).superRefine((doc, context) => {
  const ids = new Set<string>();
  const register = (id: string, path: (string | number)[]) => {
    if (ids.has(id)) {
      context.addIssue({ code: 'custom', path, message: `Duplicate id "${id}"` });
    }
    ids.add(id);
  };

  register(doc.metadata.id, ['metadata', 'id']);
  doc.sections.forEach((section, sectionIndex) => {
    register(section.id, ['sections', sectionIndex, 'id']);
    const walk = (nodes: AnyNode[], path: (string | number)[]) => {
      nodes.forEach((node, nodeIndex) => {
        const nodePath = [...path, nodeIndex];
        register(node.id, [...nodePath, 'id']);
        if (node.type === 'container') walk(node.children, [...nodePath, 'children']);
      });
    };
    walk(section.nodes, ['sections', sectionIndex, 'nodes']);
  });
});
export type AMPDocument = z.infer<typeof ampDocumentSchema>;
