import { Component, lazy, Suspense, useCallback, useEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import type { Model3DNode } from '../../specification/nodes';
import { useAMPAsset } from '../runtime-context';
import { enqueueRuntimeModelLoad } from './model-load-queue';
import { setRuntimeModelActive } from './model-activity';
import { isModelActuallyVisible, sectionClipsModelVisibility } from '../../rendering/model-visibility';
import { useModelSilhouetteHover } from '../../rendering/use-model-silhouette-hover';

const RuntimeModel3DView = lazy(() => import('./RuntimeModel3DView'));

export function RuntimeModel3D({ node }: { node: Model3DNode }) {
  const trackRef = useRef<HTMLDivElement>(null);
  const presentationRef = useRef<HTMLCanvasElement>(null);
  const src = useAMPAsset(node.src);
  const { visible, activated, resident } = useNearViewport(trackRef);
  const hovered = useModelSilhouetteHover(trackRef, presentationRef, node.behaviors.pauseOnHover, visible, 'runtime');
  const [state, setState] = useState({ key: src, ready: false, error: '' });
  const current = state.key === src ? state : { key: src, ready: false, error: '' };

  const ready = useCallback(() => setState({ key: src, ready: true, error: '' }), [src]);
  const fail = useCallback((message: string) => setState({ key: src, ready: false, error: message }), [src]);
  const rotating = visible && node.behaviors.autoRotate && !(hovered && node.behaviors.pauseOnHover);
  useEffect(() => {
    setRuntimeModelActive(node.id, rotating);
    return () => setRuntimeModelActive(node.id, false);
  }, [node.id, rotating]);

  return (
    <div
      ref={trackRef}
      className="amp-runtime-model"
      data-amp-model-hovered={hovered || undefined}
      data-amp-model-visible={String(visible)}
      data-amp-model-resident={String(resident)}
    >
      <canvas
        ref={presentationRef}
        className="amp-runtime-model-bitmap"
        aria-label={node.name}
        role="img"
        style={{ visibility: visible ? 'visible' : 'hidden' }}
      />
      {!current.ready && <div className="amp-runtime-asset-placeholder">{current.error ? `3D model unavailable: ${current.error}` : activated ? 'Loading 3D model…' : '3D model loads near viewport'}</div>}
      {resident && src && (
        <QueuedView
          key={src}
          node={node}
          src={src}
          visible={visible}
          hovered={hovered}
          presentationRef={presentationRef}
          onReady={ready}
          onError={fail}
        />
      )}
    </div>
  );
}

function QueuedView(props: {
  node: Model3DNode;
  src: string;
  visible: boolean;
  hovered: boolean;
  presentationRef: RefObject<HTMLCanvasElement | null>;
  onReady: () => void;
  onError: (message: string) => void;
}) {
  const { node, src, onReady, onError } = props;
  const [started, setStarted] = useState(false);
  const releaseRef = useRef<(() => void) | null>(null);
  useEffect(() => {
    const cancel = enqueueRuntimeModelLoad(`${node.id}:${src}`, (release) => {
      releaseRef.current = release;
      setStarted(true);
    });
    return () => {
      cancel();
      releaseRef.current?.();
      releaseRef.current = null;
    };
  }, [node.id, src]);
  const loaded = useCallback(() => {
    releaseRef.current?.();
    releaseRef.current = null;
  }, []);
  const ready = useCallback(() => {
    onReady();
  }, [onReady]);
  const fail = useCallback((message: string) => {
    releaseRef.current?.();
    releaseRef.current = null;
    onError(message);
  }, [onError]);
  if (!started) return null;
  return (
    <ModelBoundary resetKey={props.src} onError={fail}>
      <Suspense fallback={null}><RuntimeModel3DView {...props} onLoaded={loaded} onReady={ready} onError={fail} /></Suspense>
    </ModelBoundary>
  );
}

function useNearViewport(track: RefObject<HTMLElement | null>) {
  const unsupported = typeof IntersectionObserver === 'undefined';
  const [visible, setVisible] = useState(unsupported);
  const [activated, setActivated] = useState(unsupported);
  const [resident, setResident] = useState(unsupported);
  useEffect(() => {
    const element = track.current;
    if (!element || typeof IntersectionObserver === 'undefined') return;
    const root = element.closest<HTMLElement>('.amp-runtime-root');
    const section = element.closest<HTMLElement>('.amp-runtime-section');
    let eviction = 0;
    let visibilityFrame = 0;
    let visibilityFramesRemaining = 0;
    const measureVisibility = () => {
      const clips = [
        root,
        sectionClipsModelVisibility(section?.dataset.ampSectionOverflow) ? section : null,
      ]
        .filter((item): item is HTMLElement => Boolean(item))
        .map((item) => item.getBoundingClientRect());
      const nextVisible = isModelActuallyVisible(
        element.getBoundingClientRect(),
        { left: 0, top: 0, right: window.innerWidth, bottom: window.innerHeight },
        clips,
      );
      setVisible(nextVisible);
    };
    const measureSettledVisibility = () => {
      visibilityFrame = 0;
      measureVisibility();
      visibilityFramesRemaining -= 1;
      if (visibilityFramesRemaining > 0) {
        visibilityFrame = requestAnimationFrame(measureSettledVisibility);
      }
    };
    const scheduleVisibility = () => {
      // Wheel/touch events can fire before the compositor commits its final
      // scroll offset. A bounded three-frame settle prevents stale culling at
      // the exact point scrolling stops without introducing a polling loop.
      visibilityFramesRemaining = 3;
      if (!visibilityFrame) visibilityFrame = requestAnimationFrame(measureSettledVisibility);
    };
    const residencyObserver = new IntersectionObserver(([entry]) => {
      const near = Boolean(entry?.isIntersecting);
      if (near) {
        if (eviction) clearTimeout(eviction);
        setActivated(true);
        setResident(true);
      } else {
        // Keep the last bitmap visible, but release cloned/cached GPU
        // resources when a model remains far offscreen on a long document.
        eviction = window.setTimeout(() => setResident(false), 30_000);
      }
      scheduleVisibility();
    }, { rootMargin: '100% 0px' });
    const visibilityObserver = new IntersectionObserver(scheduleVisibility);
    residencyObserver.observe(element);
    visibilityObserver.observe(element);
    const resizeObserver = typeof ResizeObserver === 'undefined'
      ? null
      : new ResizeObserver(scheduleVisibility);
    resizeObserver?.observe(element);
    if (root) resizeObserver?.observe(root);
    if (section) resizeObserver?.observe(section);
    const sectionObserver = typeof MutationObserver === 'undefined' || !section
      ? null
      : new MutationObserver(scheduleVisibility);
    if (section) {
      sectionObserver?.observe(section, {
        attributes: true,
        attributeFilter: ['data-amp-section-overflow'],
      });
    }
    window.addEventListener('resize', scheduleVisibility);
    window.addEventListener('scroll', scheduleVisibility, true);
    window.addEventListener('wheel', scheduleVisibility, { passive: true });
    window.addEventListener('touchmove', scheduleVisibility, { passive: true });
    measureVisibility();
    return () => {
      residencyObserver.disconnect();
      visibilityObserver.disconnect();
      resizeObserver?.disconnect();
      sectionObserver?.disconnect();
      window.removeEventListener('resize', scheduleVisibility);
      window.removeEventListener('scroll', scheduleVisibility, true);
      window.removeEventListener('wheel', scheduleVisibility);
      window.removeEventListener('touchmove', scheduleVisibility);
      if (visibilityFrame) cancelAnimationFrame(visibilityFrame);
      if (eviction) clearTimeout(eviction);
    };
  }, [track]);
  return { visible, activated, resident };
}

class ModelBoundary extends Component<{ resetKey: string; onError: (message: string) => void; children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error: unknown) { this.props.onError(error instanceof Error ? error.message : String(error)); }
  componentDidUpdate(previous: Readonly<{ resetKey: string }>) {
    if (previous.resetKey !== this.props.resetKey && this.state.failed) this.setState({ failed: false });
  }
  render() { return this.state.failed ? null : this.props.children; }
}
