import { z } from 'zod';
import { baseNodeSchema } from './base';

export const dividerNodeSchema = baseNodeSchema.extend({
  type: z.literal('divider'),
  thickness: z.number().positive(),
  color: z.string(),
  // Named `lineStyle` (not `style`) to avoid colliding with BaseNode.style
  // (NodeStyle) -- both would otherwise be visible on the AnyNode union.
  lineStyle: z.enum(['solid', 'double', 'dashed', 'dotted', 'zigzag']),
});
export type DividerNode = z.infer<typeof dividerNodeSchema>;
