import { useLayoutEffect, useMemo, useState, type RefObject } from 'react';
import type { TextNode } from '../specification/nodes';
import {
  buildSilhouetteWrapSpacers,
  restoreStaticWrapSpacers,
  type SilhouetteSource,
  type SilhouetteWrapSpacer,
} from '../author/canvas/runtime-text-wrap';

export type ModelTextWrapSurface = 'author' | 'runtime';

const SURFACES = {
  author: {
    root: '.amp-canvas-viewport',
    section: '.amp-section',
    model: '.amp-node-model3d',
  },
  runtime: {
    root: '.amp-runtime-root',
    section: '.amp-runtime-section',
    model: '.amp-runtime-node-model3d',
  },
} as const;

const alphaScratchpads = new WeakMap<HTMLCanvasElement, HTMLCanvasElement>();
const alphaFrames = new WeakMap<HTMLCanvasElement, AlphaFrame>();
const alphaFrameTimes = new WeakMap<HTMLCanvasElement, number>();

interface AlphaFrame {
  alpha: Uint8ClampedArray;
  width: number;
  height: number;
}

/**
 * Shared Author/Reader silhouette flow. Frame throttling is deliberately local
 * to each text node: one text listener must never consume another text node's
 * update, even when both wrap around the same model.
 */
export function useLiveModelTextWrap(
  containerRef: RefObject<HTMLDivElement | null>,
  node: TextNode,
  surface: ModelTextWrapSurface,
) {
  const [spacers, setSpacers] = useState<SilhouetteWrapSpacer[]>([]);
  const settings = node.runtimeWrap;
  const staticEnabled = settings?.static?.enabled ?? false;
  const staticReader = surface === 'runtime' && staticEnabled;
  const staticAuthor = surface === 'author' && staticEnabled;
  const staticReady = settings?.static?.baked?.state !== 'pending';
  const restoredStaticSpacers = useMemo(
    () => restoreStaticWrapSpacers(settings?.static?.spacers ?? [], settings?.margin ?? 0),
    [settings?.margin, settings?.static?.spacers],
  );

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container || !settings?.enabled || staticReader || staticAuthor) {
      setSpacers((current) => current.length ? [] : current);
      return;
    }

    const selectors = SURFACES[surface];
    const root = container.closest<HTMLElement>(selectors.root) ?? document;
    const section = container.closest<HTMLElement>(selectors.section) ?? root;
    const targetIds = settings.targetNodeIds ?? [];
    const getTargets = () => {
      if (targetIds.length) {
        return targetIds
          .map((id) => root.querySelector<HTMLElement>(`[data-node-id="${safeSelector(id)}"]`))
          .filter((target): target is HTMLElement => Boolean(target) && target?.dataset.ampTextWrap === 'true');
      }
      return Array.from(section.querySelectorAll<HTMLElement>(`${selectors.model}[data-amp-text-wrap="true"]`));
    };

    let targets = getTargets();
    let pendingFrame = 0;
    let disposed = false;
    const localFrameTimes = new WeakMap<HTMLCanvasElement, number>();

    const measure = () => {
      pendingFrame = 0;
      const host = container.getBoundingClientRect();
      const scale = container.offsetWidth > 0 ? host.width / container.offsetWidth : 1;
      if (!Number.isFinite(scale) || scale <= 0) return;
      const silhouetteMode = (settings.mode ?? 'silhouette') === 'silhouette';
      const sources: SilhouetteSource[] = targets.map((target, index) => {
        const canvas = target.querySelector<HTMLCanvasElement>('canvas');
        const rect = target.getBoundingClientRect();
        const projection = modelProjection(target, rect, scale);
        const captured = silhouetteMode && canvas ? getAlphaFrame(canvas) : null;
        return {
          id: target.dataset.nodeId ?? String(index),
          rect,
          alpha: captured?.alpha ?? null,
          alphaWidth: captured?.width ?? 0,
          alphaHeight: captured?.height ?? 0,
          projection: captured ? projection : undefined,
        };
      });
      const next = buildSilhouetteWrapSpacers(host, sources, {
        side: settings.side,
        margin: settings.margin,
        alphaThreshold: settings.alphaThreshold ?? 0.05,
        scale,
      });
      setSpacers((current) => sameSpacers(current, next) ? current : next);
    };

    const scheduleMeasure = () => {
      if (disposed) return;
      if (!pendingFrame) pendingFrame = requestAnimationFrame(measure);
    };
    const resizeObserver = typeof ResizeObserver === 'undefined'
      ? null
      : new ResizeObserver(scheduleMeasure);
    resizeObserver?.observe(container);
    targets.forEach((target) => resizeObserver?.observe(target));

    const refreshTargets = () => {
      const nextTargets = getTargets();
      const nextSet = new Set(nextTargets);
      targets.forEach((target) => {
        if (!nextSet.has(target)) resizeObserver?.unobserve(target);
      });
      nextTargets.forEach((target) => {
        if (!targets.includes(target)) resizeObserver?.observe(target);
      });
      targets = nextTargets;
      scheduleMeasure();
    };

    const handleModelFrame = (event: Event) => {
      const canvas = event.target;
      if (!(canvas instanceof HTMLCanvasElement)) return;
      const target = canvas.closest<HTMLElement>(selectors.model);
      if (!target || !targets.includes(target)) return;
      if ((settings.mode ?? 'silhouette') !== 'silhouette') return;
      const now = performance.now();
      const interval = 1000 / Math.max(1, settings.updateFps ?? 12);
      if (now - (alphaFrameTimes.get(canvas) ?? -Infinity) >= interval) {
        alphaFrameTimes.set(canvas, now);
        refreshAlphaFrame(canvas);
      }
      if (now - (localFrameTimes.get(canvas) ?? -Infinity) < interval) return;
      localFrameTimes.set(canvas, now);
      scheduleMeasure();
    };

    const mutationObserver = typeof MutationObserver === 'undefined'
      ? null
      : new MutationObserver(refreshTargets);
    if (root instanceof Node) {
      mutationObserver?.observe(root, { childList: true, subtree: true });
    }
    root.addEventListener('amp-model-frame', handleModelFrame);
    window.addEventListener('resize', scheduleMeasure);
    window.addEventListener('scroll', scheduleMeasure, true);
    window.addEventListener('pageshow', scheduleMeasure);
    document.addEventListener('visibilitychange', scheduleMeasure);
    void document.fonts?.ready.then(scheduleMeasure);
    measure();

    return () => {
      disposed = true;
      resizeObserver?.disconnect();
      mutationObserver?.disconnect();
      root.removeEventListener('amp-model-frame', handleModelFrame);
      window.removeEventListener('resize', scheduleMeasure);
      window.removeEventListener('scroll', scheduleMeasure, true);
      window.removeEventListener('pageshow', scheduleMeasure);
      document.removeEventListener('visibilitychange', scheduleMeasure);
      if (pendingFrame) cancelAnimationFrame(pendingFrame);
    };
  }, [containerRef, settings, staticAuthor, staticReader, surface]);

  if (!settings?.enabled) return [];
  if (staticAuthor) return [];
  return staticReader ? (staticReady ? restoredStaticSpacers : []) : spacers;
}

function getAlphaFrame(canvas: HTMLCanvasElement) {
  return alphaFrames.get(canvas) ?? refreshAlphaFrame(canvas);
}

function refreshAlphaFrame(canvas: HTMLCanvasElement): AlphaFrame | null {
  const frame = readAlphaFrame(canvas);
  if (frame?.alpha.some((value) => value > 0)) {
    alphaFrames.set(canvas, frame);
    return frame;
  }
  // Canvas attributes can briefly reset between a responsive resize and the
  // next complete model snapshot. Preserve a valid contour; if none exists,
  // return null so wrapping safely falls back to the model container.
  return alphaFrames.get(canvas) ?? null;
}

function readAlphaFrame(canvas: HTMLCanvasElement): AlphaFrame | null {
  if (!canvas.width || !canvas.height) return null;
  let scratch = alphaScratchpads.get(canvas);
  if (!scratch) {
    scratch = document.createElement('canvas');
    alphaScratchpads.set(canvas, scratch);
  }
  const maxDimension = 128;
  const ratio = Math.min(1, maxDimension / Math.max(canvas.width, canvas.height));
  const width = Math.max(1, Math.round(canvas.width * ratio));
  const height = Math.max(1, Math.round(canvas.height * ratio));
  if (scratch.width !== width) scratch.width = width;
  if (scratch.height !== height) scratch.height = height;
  const context = scratch.getContext('2d', { willReadFrequently: true });
  if (!context) return null;
  try {
    context.clearRect(0, 0, width, height);
    context.drawImage(canvas, 0, 0, width, height);
    const rgba = context.getImageData(0, 0, width, height).data;
    const alpha = new Uint8ClampedArray(width * height);
    for (let pixel = 0; pixel < alpha.length; pixel += 1) alpha[pixel] = rgba[pixel * 4 + 3]!;
    return { alpha, width, height };
  } catch {
    return null;
  }
}

function sameSpacers(a: SilhouetteWrapSpacer[], b: SilhouetteWrapSpacer[]) {
  return a.length === b.length && a.every((left, index) => {
    const right = b[index];
    return Boolean(right)
      && left.id === right!.id
      && left.side === right!.side
      && left.top === right!.top
      && left.width === right!.width
      && left.height === right!.height
      && left.margin === right!.margin
      && left.shapeOutside === right!.shapeOutside;
  });
}

function safeSelector(value: string) {
  return typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(value) : value.replace(/["\\]/g, '\\$&');
}

function modelProjection(
  target: HTMLElement,
  rect: DOMRect,
  scale: number,
): NonNullable<SilhouetteSource['projection']> {
  const match = target.style.transform.match(/rotate\(\s*(-?(?:\d+\.?\d*|\.\d+))deg\s*\)/i);
  const rotation = match ? Number(match[1]) * Math.PI / 180 : 0;
  return {
    centerX: (rect.left + rect.right) / 2,
    centerY: (rect.top + rect.bottom) / 2,
    width: Math.max(1, target.offsetWidth * scale),
    height: Math.max(1, target.offsetHeight * scale),
    rotation: Number.isFinite(rotation) ? rotation : 0,
  };
}
