import { z } from 'zod';
import { boxSpacingSchema, pointSchema, sizeSchema } from './units';

export const layoutModeSchema = z.enum([
  'flow',
  'float-left',
  'float-right',
  'inline',
  'center',
  'absolute',
]);
export type LayoutMode = z.infer<typeof layoutModeSchema>;

export const anchorSchema = z.enum([
  'top-left',
  'top-center',
  'top-right',
  'center-left',
  'center',
  'center-right',
  'bottom-left',
  'bottom-center',
  'bottom-right',
]);
export type Anchor = z.infer<typeof anchorSchema>;

export const overflowSchema = z.enum(['visible', 'hidden', 'scroll']);
export type Overflow = z.infer<typeof overflowSchema>;

// Position/size use AMP's fixed Specification reference coordinate space.
// Runtime applies one uniform viewport-derived scale to the whole canvas, so
// authored layout never reflows or drifts across screen aspect ratios.
export const nodeLayoutSchema = z.object({
  mode: layoutModeSchema,
  position: pointSchema.optional(),
  size: sizeSchema,
  rotation: z.number().optional(),
  margin: boxSpacingSchema.partial().optional(),
  padding: boxSpacingSchema.partial().optional(),
  align: z.enum(['left', 'center', 'right', 'justify']).optional(),
  zIndex: z.number().int().optional(),
  anchor: anchorSchema.optional(),
  overflow: overflowSchema.optional(),
});
export type NodeLayout = z.infer<typeof nodeLayoutSchema>;
