import type { DividerNode } from '../../specification/nodes';

export function RuntimeDivider({ node }: { node: DividerNode }) {
  if (node.lineStyle === 'zigzag') {
    const height = Math.max(8, node.thickness * 4);
    const amplitude = height / 2 - node.thickness;
    return <svg aria-hidden width="100%" height={height} preserveAspectRatio="none" className="amp-runtime-divider"><defs><pattern id={`runtime-zigzag-${node.id}`} width="20" height={height} patternUnits="userSpaceOnUse"><path d={`M 0 ${height / 2} L 5 ${height / 2 - amplitude} L 15 ${height / 2 + amplitude} L 20 ${height / 2}`} fill="none" stroke={node.color} strokeWidth={node.thickness} strokeLinejoin="round" /></pattern></defs><rect width="100%" height={height} fill={`url(#runtime-zigzag-${node.id})`} /></svg>;
  }
  return <div className="amp-runtime-divider" style={{ width: '100%', height: 0, borderTop: `${node.thickness}px ${node.lineStyle} ${node.color}` }} />;
}
