import { z } from 'zod';
import { baseNodeSchema, type BaseNode } from './base';
import { textNodeSchema, type TextNode } from './text';
import { imageNodeSchema, type ImageNode } from './image';
import { videoNodeSchema, type VideoNode } from './video';
import { model3DNodeSchema, type Model3DNode } from './model3d';
import { audioNodeSchema, type AudioNode } from './audio';
import { spacerNodeSchema, type SpacerNode } from './spacer';
import { dividerNodeSchema, type DividerNode } from './divider';
import { tableNodeSchema, type TableNode } from './table';

export * from './base';
export * from './text';
export * from './image';
export * from './video';
export * from './model3d';
export * from './audio';
export * from './spacer';
export * from './divider';
export * from './table';

// Container is a Node like any other, so nesting (and future node types)
// compose naturally instead of needing a separate fixed tier in the hierarchy.
export interface ContainerNode extends BaseNode {
  type: 'container';
  children: AnyNode[];
}

export type AnyNode =
  | TextNode
  | ImageNode
  | VideoNode
  | Model3DNode
  | AudioNode
  | SpacerNode
  | DividerNode
  | TableNode
  | ContainerNode;

// nodeSchema and containerNodeSchema are mutually recursive. Only the
// `children` field is wrapped in z.lazy (deferred until first .parse()) so
// containerNodeSchema itself stays a plain discriminable object schema.
export const containerNodeSchema = baseNodeSchema.extend({
  type: z.literal('container'),
  children: z.lazy(() => z.array(nodeSchema)),
});

export const nodeSchema: z.ZodType<AnyNode> = z.discriminatedUnion('type', [
  textNodeSchema,
  imageNodeSchema,
  videoNodeSchema,
  model3DNodeSchema,
  audioNodeSchema,
  spacerNodeSchema,
  dividerNodeSchema,
  tableNodeSchema,
  containerNodeSchema,
]);
